<script setup lang="ts">
import { computed,onMounted,onUnmounted,ref } from 'vue'
import { useRoute } from 'vue-router'
import { api,errorText,hasRole } from '../api'
import { time,shortId,useLoad } from '../composables'
import type { AgentRun,IncidentDetail } from '../types'
import PageState from '../components/PageState.vue'
import AgentReviewPanel from '../components/AgentReviewPanel.vue'
import { agentStatus,nodeNames } from '../diagnosis'
const id=String(useRoute().params.id),{data,loading,error,load}=useLoad(async()=>{const run=await api<AgentRun>('/agent-runs/'+id);const incident=await api<IncidentDetail>('/incidents/'+run.incidentId);return {...run,canOperate:incident.canOperate}}),busy=ref(false),reason=ref(''),saveError=ref('')
const active=computed(()=>data.value&&['QUEUED','RUNNING','WAITING_HUMAN'].includes(data.value.status))
async function retry(){busy.value=true;saveError.value='';try{await api('/agent-runs/'+id+'/retry',{method:'POST',body:{reason:reason.value}});reason.value='';await load()}catch(e){saveError.value=errorText(e)}finally{busy.value=false}}
function citationLink(sectionId:string){const section=data.value?.runbookEvidence.find(s=>s.sectionId===sectionId);return section?{path:'/runbooks/'+section.runbookId,query:{version:String(section.version),section:section.sectionId},hash:'#'+section.sectionId}:{path:'/targets/'+data.value?.targetId,query:{tab:'history'}}}
function refresh(){if(!document.hidden&&!loading.value)void load()}
onMounted(()=>{void load();window.addEventListener('focus',refresh)});const timer=setInterval(()=>{if(active.value)refresh()},3000);onUnmounted(()=>{clearInterval(timer);window.removeEventListener('focus',refresh)})
</script>
<template><RouterLink :to="data?'/incidents/'+data.incidentId:'/incidents'" class="back-link">← 事故详情</RouterLink><PageState :loading="loading&&!data" :error="error" @retry="load"><template v-if="data"><div class="page-heading"><div><div class="title-line"><h1>只读诊断</h1><span class="env-tag">{{ data.modelName }}</span><strong class="run-status" :class="data.status.toLowerCase()">{{ agentStatus[data.status]||data.status }}</strong></div><p>任务 {{ shortId(data.id) }} · {{ time(data.createdAt) }}</p></div><button class="btn" :disabled="loading" @click="load">刷新状态</button></div><div class="notice">{{ data.modelName==='mock'?'当前使用 mock 模式整理本地证据。':'报告由已配置的模型生成，仍需人工核对。' }} 平台不会执行命令；置信度不能作为统计概率或根因确认。</div><section class="panel graph-progress" aria-label="诊断节点状态"><ol><li v-for="(step,index) in data.steps" :key="step.node" :class="step.status.toLowerCase()"><span>{{ step.status==='COMPLETED'?'✓':index+1 }}</span><strong>{{ nodeNames[step.node] }}</strong><small>{{ step.status==='COMPLETED'?'已确认':step.status==='FAILED'?'未完成':step.status==='SKIPPED'?'已跳过':'等待结果确认' }}</small></li></ol><p class="form-hint">{{ active?'任务由后台持久化队列处理，状态每 3 秒刷新。节点在结果通过 Java 引用校验后确认完成。':'节点状态来自已保存的任务记录。' }} <span v-if="data.errorCode">最近错误：{{ data.errorCode }} · 尝试 {{ data.attempts }}/5</span></p></section><section v-if="data.deliveryState==='DEAD'" class="panel retry-panel"><h2>诊断未完成</h2><p v-if="data.errorCode==='AGENT_MODEL_OUTCOME_UNKNOWN'" class="notice">模型调用是否完成无法确认，为避免重复调用，本任务不会再次发送。请先核对模型服务的调用记录；需要新诊断时，从事故详情明确发起。</p><p v-else>错误码 {{ data.errorCode }}。请先确认内部诊断服务与配置，再由管理员明确重试。</p><form v-if="hasRole('OPS_ADMIN') && data.errorCode!=='AGENT_MODEL_OUTCOME_UNKNOWN'" @submit.prevent="retry"><div v-if="saveError" class="error-message" role="alert">{{ saveError }}</div><label>重试理由<input v-model="reason" required maxlength="500" /></label><button class="btn" :disabled="busy||!reason.trim()">{{ busy?'提交中…':'重新加入队列' }}</button></form></section><template v-if="data.result"><AgentReviewPanel :run="data" :can-operate="data.canOperate" @changed="load" /><section class="panel report-block"><div class="eyebrow">OBSERVED · 观测事实</div><h2>检查摘要</h2><p class="report-summary">{{ data.result.summary }}</p><div v-if="data.checkEvidence.length" class="table-scroll"><table><thead><tr><th>结果</th><th>HTTP</th><th>完成时间</th><th>证据</th></tr></thead><tbody><tr v-for="check in data.checkEvidence" :key="check.runId"><td>{{ check.outcome }}</td><td>{{ check.statusCode||check.errorCode||'—' }}</td><td>{{ time(check.completedAt) }}</td><td><code :title="check.runId">{{ shortId(check.runId) }}</code></td></tr></tbody></table></div><p v-else class="muted">当前窗口没有检查证据。</p></section><div class="report-columns"><section class="panel report-block"><div class="eyebrow">INFERRED · 待确认推断</div><h2>诊断假设</h2><article v-for="(hypothesis,index) in data.result.hypotheses" :key="index" class="hypothesis"><p>{{ hypothesis.text }}</p><small class="muted">参考置信度 {{ (hypothesis.confidence*100).toFixed(0) }}% · {{ hypothesis.evidenceIds.length }} 条引用</small></article><p v-if="!data.result.hypotheses.length" class="muted">证据不足或没有异常检查，未形成故障假设。</p><h3>建议的人工核对</h3><ol class="next-steps"><li v-for="(step,index) in data.result.nextSteps" :key="index">{{ step.text }}<small class="muted">{{ ({LOW:'低风险',MEDIUM:'中风险',HIGH:'高风险'} as Record<string,string>)[step.risk]||step.risk }} · 需人工审阅</small></li></ol></section><section class="panel report-block"><div class="eyebrow">UNKNOWN · 不确定项</div><h2>结论的边界</h2><ul class="uncertainties"><li v-for="item in data.result.uncertainties" :key="item">{{ item==='insufficient_evidence'?'检查证据不足，无法确定故障原因。':item }}</li></ul><p class="form-hint">图版本 {{ data.graphVersion }} · provider {{ data.modelName }}</p></section></div><section class="panel report-block"><h2>证据引用 <span class="heading-count">{{ data.result.citations.length }}</span></h2><p class="muted">手册链接指向任务当时冻结的已发布版本。</p><ul class="citation-list"><li v-for="citation in data.result.citations" :key="citation.id"><RouterLink :to="citation.kind==='RUNBOOK_SECTION'?citationLink(citation.id):{path:'/targets/'+data.targetId,query:{tab:'history'}}">{{ citation.kind==='RUNBOOK_SECTION'?'运行手册 v'+citation.version:'检查记录' }} · {{ shortId(citation.id) }} ↗</RouterLink><small v-if="citation.time" class="muted">{{ time(citation.time) }}</small><small v-if="citation.hash" class="mono muted" :title="citation.hash">SHA-256 {{ citation.hash.slice(0,12) }}…</small></li></ul><p v-if="!data.result.citations.length" class="muted">没有可引用证据。</p></section></template><section v-else-if="active" class="panel waiting-report"><h2>等待诊断报告</h2><p>可以离开此页，任务与检查点会保存在服务端。结果通过引用校验后将在这里显示。</p></section></template></PageState></template>
<style scoped>.run-status{font-size:13px;color:var(--muted)}.run-status.completed{color:var(--good)}.run-status.failed{color:var(--danger)}.graph-progress{padding:24px;margin:24px 0}.graph-progress ol{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));list-style:none;padding:0;margin:0 0 20px;gap:16px}.graph-progress li{display:grid;gap:6px;font-size:12px}.graph-progress li>span{width:26px;height:26px;display:grid;place-items:center;background:#eef2ed;color:var(--muted);border-radius:50%;font-size:12px}.graph-progress li.completed>span{background:#dceee3;color:var(--good)}.graph-progress li.failed>span{background:#f8e9e6;color:var(--danger)}.graph-progress li small{color:var(--muted);font-size:10px}.report-block,.retry-panel,.waiting-report{padding:24px;margin-bottom:24px;min-width:0}.report-block h2{margin:4px 0 16px}.report-block h3{margin:24px 0 12px}.report-summary{margin-bottom:20px;font-size:16px}.eyebrow{font-size:10px;letter-spacing:.1em;color:var(--muted)}.report-columns{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);gap:24px}.hypothesis{border-bottom:1px solid var(--border);padding:12px 0}.next-steps,.uncertainties{padding-left:20px}.next-steps li,.uncertainties li{margin:12px 0}.next-steps small{display:block}.citation-list{list-style:none;margin:16px 0 0;padding:0}.citation-list li{display:flex;flex-wrap:wrap;gap:12px;padding:12px 0;border-bottom:1px solid var(--border)}.citation-list a{color:var(--accent);font-weight:600}.retry-panel p{margin:12px 0}.retry-panel form{display:flex;flex-wrap:wrap;gap:16px;align-items:end}.retry-panel label{flex:1;min-width:180px}.waiting-report p{margin-top:12px;color:var(--muted)}@media(max-width:800px){.report-columns{grid-template-columns:1fr;gap:0}.graph-progress ol{grid-template-columns:repeat(3,minmax(0,1fr));row-gap:20px}}@media(max-width:500px){.report-block,.graph-progress,.waiting-report{padding:18px}.graph-progress ol{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>
